from dataclasses import replace
from services.contracts import DEFAULT_TECHNICAL_INTELLIGENCE_POLICY
def default_policy():return DEFAULT_TECHNICAL_INTELLIGENCE_POLICY
def policy_variant(*,incomplete=None,insufficient=None,conflict=None):return replace(DEFAULT_TECHNICAL_INTELLIGENCE_POLICY,incomplete_timeframe_behavior=incomplete or DEFAULT_TECHNICAL_INTELLIGENCE_POLICY.incomplete_timeframe_behavior,insufficient_history_behavior=insufficient or DEFAULT_TECHNICAL_INTELLIGENCE_POLICY.insufficient_history_behavior,conflicting_timeframe_behavior=conflict or DEFAULT_TECHNICAL_INTELLIGENCE_POLICY.conflicting_timeframe_behavior)
